// ===================================
// Interface strings — English, the source of every other language.
//
// A key names the place, not the words: `settings.language.caption`, not
// `language`. The words can be re-written freely; a key, once translated, is
// renamed only together with every language file. `{name}` is filled in by
// t(key, { name }) — every translation must keep the same placeholders
// (`npm run check:i18n` checks it).
//
// Strings for official papers (PSC / flag PDFs) do NOT come here: those stay
// English whatever the device says. Neither does anything the crew typed.
// ===================================

