  "hos.invIntro": "Counting the chest against the books. Inventory: go round the cabinets with the list, change only what you count differently — the books then follow the count, and the differences print. Controlled drugs: the Master’s monthly count with a witness, and the handover when the responsible officer changes — the outgoing and the incoming count together and both sign. Landing report: out-of-date stock handed ashore for destruction — you hand over, the person ashore signs by hand; the controlled drugs on their own report, with a witness.",
