  "scn.sub": "An ISM AI Pilot QR label, or a serial / asset tag. A crew or passenger card opens the person — crossings are recorded from the gangway page.",
  "scn.noCamHere": "No camera here",
  "scn.noCamBody": "Scanning is a phone job — this build has no camera. Type the code or the serial below instead; the lookup is exactly the one the scanner uses.",
  "scn.deskCam": "This computer's camera can read a label held up to it. On a desk machine the code is usually easier to type — the box below runs exactly the same lookup.",
