  "scn.needCam": "ISM AI Pilot needs the camera to read QR labels and barcodes off equipment. Nothing is recorded — the frame is decoded and discarded.",
  "scn.ready": "Ready for the next card.",
  "scn.staleTitle": "This label is not in the register",
  "scn.staleBody": "The sticker is one of ours, but the item it points to is gone — deleted, or this device is holding an older copy of the register than the vessel is. Check the category list, and the sync state, before re-creating anything: re-adding it here would put back, as a new item, something somebody removed on purpose.",
  "scn.again": "Scan again",
  "scn.unknownTitle": "Not on file",
  "scn.unknownBody": "Nothing in the register carries this code. If it is the maker's own barcode, open the item and put it in the “Serial / ID” field — then this code will find it next time.",
  "scn.orType": "Or type the code",
  "scn.orTypeBody": "For a label too scraped or faded to scan, if the characters are still readable.",
  "scn.serialPh": "Serial / ID number",
